// Replay loading (offline) + live backend detection (FastAPI on :8000). Every number shown in the UI comes from
// these JSON files (generated by scripts/make_replay.py from results/*.csv) or from the live backend.
export const API = (import.meta as any).env?.VITE_QGRID_API ?? 'http://localhost:8000'

export type Zone = { name: string; cx: number; cy: number; pv_kwp: number; battery_kwh: number; battery_kw: number;
  dg_kw: number; tank_m3: number; critical_frac: number; source: string;
  buildings: { name: string | null; levels: number; polygon: [number, number][] }[] }

export type Run = { p_bat: number[][]; soc: number[][]; flows: number[][]; dg_kw: number[][]; pump_on: number[][];
  tank_m3: Record<string, number[]>; net_kw: number[][]; grid_import_kw: number[]; grid_export_kw: number[];
  cum_cost_rs: number[]; cum_co2_kg: number[]; metrics: Record<string, any>; flex_start: Record<string, number>[] }

export type Scenario = {
  label: string; qiea_label: string; scenario: { key: string; date: string; day_type: string; note: string; outage: string[] | null }
  price_scenario: string; price_status: string; data_status: Record<string, string>
  campus: { name: string; credit: string; outline: [number, number][] | null; zones: Zone[]; lines: [string, string][]; line_step_kw: number }
  slots: { t: string[]; sun: { elevation_deg: number[]; azimuth_deg: number[] }; pv_kw: number[][]; load_kw: number[][];
    crit_kw: number[][]; price_import: number[]; price_export: number[]; grid_up: number[]; co2_kg_per_kwh: number }
  runs: { qgrid: Run; status_quo?: Run }; replay_matches_benchmark: boolean
  admm: { iterations: Record<string, { k: number; r_primal: number; r_dual: number; agreed: boolean; proposals: Record<string, number[]> }[]>; summary: Record<string, any>; lines: [string, string][] }
  explanations: Record<string, Record<string, string[]>>; qaoa_file: string; benchmark: Record<string, any>[]
  headline?: any; live_solve?: LiveSolve[]; provenance: Provenance
}
export type LiveSolve = { zone: string; slot: number; time: string; n_qubits: number; var_names: string[]; qubo_matrix: number[][];
  exact: { bits: string; objective: number; time_s: number }
  qaoa: { best_bits: string | null; best_objective: number | null; feasible: boolean; approx_ratio: number; p_opt: number; time_s: number;
    top: { bits: string; p: number; feasible: boolean; optimal: boolean }[] }; explanation: string[] }
export type Provenance = { git_commit: string; seeds: Record<string, number>; files: Record<string, string | null> }
export type QaoaFile = { n_qubits: number; var_names: string[]; gammas: number[]; betas: number[]; qubo_matrix: number[][];
  qubo_const: number; probs: number[]; energies: number[]; feasible: number[]; optimum: { bits: string; objective: number; p_opt: number };
  uniform_p: number; zone: string; slot: number; simulator: string; label: string; groups: Record<string, { M: number[][]; const: number }> }
export type Index = { scenarios: { key: string; date: string; note: string; replay_matches_benchmark: boolean }[]; headline: string;
  provenance: Provenance; label: string; data_status: Record<string, string>; files?: string[] }

const base = (import.meta as any).env?.BASE_URL ?? '/'

/** Thrown when a replay file is absent or is not JSON (the dev server answers missing files with index.html). */
export class MissingReplay extends Error {
  files: string[]
  constructor(files: string[]) { super(`replay data missing: ${files.join(', ')}`); this.files = files }
}

export async function getJSON<T>(name: string): Promise<T> {
  let r: Response
  try { r = await fetch(`${base}replay/${name}`) } catch { throw new MissingReplay([`replay/${name}`]) }
  const ct = r.headers.get('content-type') ?? ''
  if (!r.ok || !ct.includes('json')) throw new MissingReplay([`replay/${name}`])
  try { return await r.json() } catch { throw new MissingReplay([`replay/${name} (not valid JSON)`]) }
}

/** Which of the given replay files are missing or not JSON (HEAD-free: fetch + content-type check). */
export async function missingReplayFiles(names: string[]): Promise<string[]> {
  const out: string[] = []
  await Promise.all(names.map(async n => {
    try {
      const r = await fetch(`${base}replay/${n}`)
      if (!r.ok || !(r.headers.get('content-type') ?? '').includes('json')) out.push(`replay/${n}`)
    } catch { out.push(`replay/${n}`) }
  }))
  return out.sort()
}
export async function getCSV(name: string): Promise<Record<string, string>[]> {
  const r = await fetch(`${base}replay/${name}`)
  if (!r.ok || (r.headers.get('content-type') ?? '').includes('html')) return []
  const [head, ...rows] = (await r.text()).trim().split('\n')
  const cols = head.split(',')
  return rows.map(l => Object.fromEntries(l.split(',').map((v, i) => [cols[i], v])))
}

export async function liveAvailable(): Promise<boolean> {
  try {
    const c = new AbortController(); const t = setTimeout(() => c.abort(), 800)
    const r = await fetch(`${API}/health`, { signal: c.signal }); clearTimeout(t)
    return r.ok
  } catch { return false }
}
export async function post<T>(path: string, body: any): Promise<T> {
  const r = await fetch(`${API}${path}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
  if (!r.ok) throw new Error(`${path} ${r.status}`)
  return r.json()
}
export const fmt = (v: number, d = 0) => (v ?? 0).toLocaleString('en-IN', { maximumFractionDigits: d, minimumFractionDigits: d })
